This is a greedy solution with a lazy priority queue. I have not compiled or run it.

**Approach**

1. Keep a current time `t`, starting at 0. A library signed up at time `t` finishes at `t+T`, and scanning starts on day `t+T`. The days available to it are `D - t - T`, so it can scan at most `cap = (D-t-T)*M` books.
2. For each library, the value is the sum of the top `cap` scores among its books not yet taken. Score per signup day is `value / T`.
3. Selection uses a lazy max-heap keyed on that ratio. Pop the top library and recompute its value at the current `t`. If the recomputed ratio is at least the next heap top, accept it. Otherwise push it back with the new ratio. Ratios only fall over time, so stale keys are always upper bounds, which makes the lazy approach valid.
4. Recomputing a library costs O(N log N) with a partial sort. Libraries total up to 1e6 books, and the number of recomputations is bounded by a cap on iterations, so I limit the work for safety.
5. Libraries are stored with their books sorted by score descending. To recompute, scan the list, skip used books, and take up to `cap` of them. The scan stops once `cap` books are collected. A lazy front pointer skips used books at the start of the list, and `cap` is at most `D*M`.
6. Cost is bounded by a time check. Each recomputation scans at most the library's list, so the total could be large. I add a clock check: after about 8 seconds, accept the popped library with its recomputed value without further re-pushing.
7. When a library is accepted, `t += T`, its chosen books are marked used, and they are output in descending score order. Only libraries with at least one book to scan are output, so K ≥ 1.
8. A library is skipped if `t+T >= D`, which means it has no days left.

Because the output order is signup order and each library's books are listed in the order scanned, the output is valid. Values are recomputed with ties broken by library index in the heap, which keeps it deterministic.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int B,L,D;
    scanf("%d %d %d",&B,&L,&D);
    vector<int> s(B);
    for(auto&x:s)scanf("%d",&x);
    vector<vector<int>> bk(L);
    vector<int> T(L),M(L);
    for(int j=0;j<L;j++){
        int n;
        scanf("%d %d %d",&n,&T[j],&M[j]);
        bk[j].resize(n);
        for(auto&x:bk[j])scanf("%d",&x);
        sort(bk[j].begin(),bk[j].end(),[&](int a,int b){
            if(s[a]!=s[b])return s[a]>s[b];
            return a<b;});
    }
    vector<char> used(B,0);
    vector<int> front(L,0);
    long long t=0;
    auto eval=[&](int j,long long tt,vector<int>*out)->double{
        long long days=D-tt-T[j];
        if(days<=0)return 0;
        long long cap=days*M[j];
        auto&v=bk[j];
        int&f=front[j];
        while(f<(int)v.size()&&used[v[f]])f++;
        long long sum=0,c=0;
        for(size_t i=f;i<v.size()&&c<cap;i++){
            if(used[v[i]])continue;
            sum+=s[v[i]];c++;
            if(out)out->push_back(v[i]);
        }
        return (double)sum/T[j];
    };
    priority_queue<pair<double,int>> pq;
    for(int j=0;j<L;j++){
        double r=eval(j,0,nullptr);
        if(r>0)pq.push({r,-j});
    }
    auto start=chrono::steady_clock::now();
    vector<pair<int,vector<int>>> res;
    int iter=0;
    bool late=false;
    while(!pq.empty()){
        auto [r,nj]=pq.top();pq.pop();
        int j=-nj;
        if(!late&&(++iter&255)==0){
            double el=chrono::duration<double>(chrono::steady_clock::now()-start).count();
            if(el>7.0)late=true;
        }
        double nr=eval(j,t,nullptr);
        if(nr<=0)continue;
        if(!late&&!pq.empty()&&nr<pq.top().first){
            pq.push({nr,-j});
            continue;
        }
        vector<int> out;
        eval(j,t,&out);
        if(out.empty())continue;
        for(int b:out)used[b]=1;
        t+=T[j];
        res.push_back({j,out});
    }
    string o;
    o+=to_string(res.size())+"\n";
    for(auto&p:res){
        o+=to_string(p.first)+" "+to_string(p.second.size())+"\n";
        for(size_t i=0;i<p.second.size();i++){
            if(i)o+=' ';
            o+=to_string(p.second[i]);
        }
        o+="\n";
    }
    fputs(o.c_str(),stdout);
}
